+                                                                               \
+    explicit HandleType(oop* raw_handle) : BaseType(raw_handle) {}             \
+                                                                               \
+  public:                                                                      \
+    /* Constructors */                                                         \
+    HandleType() : BaseType() {}                                               \
+    inline HandleType(Thread* thread, OopType obj);                            \
+                                                                               \
+    static HandleType make(oop* raw_handle) { return HandleType(raw_handle); } \
+                                                                               \
